        }
        const rest = (if ((name[0] == 58)) name[1..] else name);
        if ((rest.len == 0)) {
            return true;
        }
        for (cp_iter_slice(rest)) |ch| {
            _ = &ch;
            switch (ch) {
97...122, 48...57, '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~' => {

},
else => {
return true;
},
}
        }
        return false;
}

pub fn isMalformedFieldValue(value: []const u8) bool {
        return (!isValidHeaderValue(value));
}

